/**
 * Hashtags, built from the seed in code.
 *
 * These were being generated by the AI, which is wrong on three counts: they
 * are not creative writing, the model has no idea which tags actually get
 * reach, and it invents plausible-looking ones that nobody searches (the local
 * model produced "#celestialquirks" and "#planetsinyourface"). A fixed bank
 * keyed to the seed is cheaper, more consistent, and editable once real
 * performance data exists.
 *
 * Instagram now favours a handful of relevant tags over a wall of them, so the
 * default cap is 5.
 */

const fs = require('fs');
const path = require('path');

const FILE = path.join(__dirname, '..', 'hashtags.json');

let config = null;
function load() {
  if (!config) config = JSON.parse(fs.readFileSync(FILE, 'utf8'));
  return config;
}

/** Small deterministic hash so the same seed always yields the same tags. */
function hash(str) {
  let h = 2166136261;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}

/**
 * Rotates through a list from an offset rather than picking randomly, so
 * consecutive posts get different tags instead of re-rolling the same
 * favourites.
 */
function take(list, count, offset) {
  const out = [];
  for (let i = 0; i < Math.min(count, list.length); i++) {
    out.push(list[(offset + i) % list.length]);
  }
  return out;
}

/**
 * @param {object} seed  needs { mood, subject, angle, date }
 * @param {number} [max] override the configured cap
 * @returns {string[]} hashtags with the leading '#'
 */
function hashtagsFor(seed, max) {
  const cfg = load();
  const limit = max || cfg.max || 5;
  const offset = hash(`${seed.angle}|${seed.subject}|${seed.date}`);

  const subject = cfg.bySubject[seed.subject] || [];
  const mood = cfg.byMood[seed.mood] || [];

  // Weighted toward the general tags — they carry the reach — then one
  // subject tag and one or two mood tags for relevance.
  const picked = [
    ...take(cfg.core, 2, offset),
    ...take(subject, 1, offset),
    ...take(mood, limit - 3, offset)
  ];

  // De-duplicate while preserving order, then top up from core if a bank was
  // short (a mood with fewer tags than the cap expects).
  const seen = new Set();
  const out = [];
  for (const tag of picked) {
    if (!seen.has(tag)) {
      seen.add(tag);
      out.push(tag);
    }
  }
  let i = 0;
  while (out.length < limit && i < cfg.core.length) {
    const tag = cfg.core[(offset + i++) % cfg.core.length];
    if (!seen.has(tag)) {
      seen.add(tag);
      out.push(tag);
    }
  }

  return out.slice(0, limit).map((t) => (t.startsWith('#') ? t : `#${t}`));
}

module.exports = { hashtagsFor };
